/* ==========================================================================
   Axiom — design tokens
   A drafting-table instrument: pale paper chassis, dark glass screens.
   Every colour, type, space, radius and motion value in this app lives here.
   ========================================================================== */

:root {
  /* ---------- chassis (paper) ---------- */
  --paper: #e8ece6;
  --paper-raised: #f5f7f2;
  --paper-sunken: #dce3db;
  --paper-deep: #ccd6cc;
  --line: #c3cec4;
  --line-strong: #a3b3a8;
  --ink: #15211e;
  --ink-soft: #50645c;
  --ink-faint: #788c83;

  /* ---------- screen (dark glass) ---------- */
  --screen: #0c1714;
  --screen-raised: #13231f;
  --screen-edge: rgba(226, 238, 231, 0.09);
  --screen-line: rgba(226, 238, 231, 0.11);
  --screen-ink: #e3efe8;
  --screen-soft: #93ada2;
  --screen-faint: #628073;
  --screen-sheen: linear-gradient(180deg, rgba(255, 255, 255, 0.055), rgba(255, 255, 255, 0) 46%);

  /* ---------- mode accents: scientific ---------- */
  --accent-sci: #0f8c7d;
  --accent-sci-strong: #0a5f55;
  --accent-sci-bright: #52e0c4;
  --accent-sci-soft: rgba(15, 140, 125, 0.12);
  --accent-sci-glow: rgba(82, 224, 196, 0.3);
  --accent-sci-ghost: rgba(15, 140, 125, 0.22);
  --page-sci: #e6ece6;

  /* ---------- mode accents: graph ---------- */
  --accent-graph: #c4550f;
  --accent-graph-strong: #8a3a08;
  --accent-graph-bright: #ff9d52;
  --accent-graph-soft: rgba(196, 85, 15, 0.12);
  --accent-graph-glow: rgba(255, 157, 82, 0.28);
  --accent-graph-ghost: rgba(196, 85, 15, 0.22);
  --page-graph: #e2e8ea;

  /* ---------- mode accents: date ---------- */
  --accent-date: #6f3fa6;
  --accent-date-strong: #502a7c;
  --accent-date-bright: #c8a2ff;
  --accent-date-soft: rgba(111, 63, 166, 0.12);
  --accent-date-glow: rgba(200, 162, 255, 0.3);
  --accent-date-ghost: rgba(111, 63, 166, 0.22);
  --page-date: #e9e6ee;

  /* ---------- active mode (overridden on body[data-mode]) ---------- */
  --accent: var(--accent-sci);
  --accent-strong: var(--accent-sci-strong);
  --accent-bright: var(--accent-sci-bright);
  --accent-soft: var(--accent-sci-soft);
  --accent-glow: var(--accent-sci-glow);
  --accent-ghost: var(--accent-sci-ghost);
  --page: var(--page-sci);
  --on-accent: #f5f7f2;

  /* ---------- mode materials (textures, one per mode) ---------- */
  --mode-texture: radial-gradient(var(--accent-sci-ghost) 1px, transparent 1.4px);
  --mode-texture-size: 18px 18px;
  --texture-sci: radial-gradient(var(--accent-sci-ghost) 1px, transparent 1.4px);
  --texture-sci-size: 18px 18px;
  --texture-graph: linear-gradient(to right, var(--accent-graph-ghost) 1px, transparent 1px),
    linear-gradient(to bottom, var(--accent-graph-ghost) 1px, transparent 1px);
  --texture-graph-size: 26px 26px;
  --texture-date: linear-gradient(to bottom, var(--accent-date-ghost) 1px, transparent 1px);
  --texture-date-size: 100% 30px;

  /* ---------- typography ---------- */
  /* System stacks only: no web fonts, no CDN, works from file:// */
  --font-ui: system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial,
    "Noto Sans", sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas,
    "Liberation Mono", "DejaVu Sans Mono", monospace;

  --text-2xs: 0.625rem;
  --text-xs: 0.6875rem;
  --text-sm: 0.8125rem;
  --text-base: 0.9375rem;
  --text-md: 1.0625rem;
  --text-lg: 1.3125rem;
  --text-xl: clamp(1.625rem, 1.25rem + 1.3vw, 2.125rem);
  --text-2xl: clamp(2.125rem, 1.4rem + 2.6vw, 3.25rem);
  --text-readout: clamp(2.25rem, 1.3rem + 4.6vw, 4.25rem);
  --text-spine: clamp(1.75rem, 1rem + 2.6vw, 3.25rem);
  --text-spine-wide: clamp(3.5rem, 2rem + 5vw, 5.5rem);

  --weight-regular: 400;
  --weight-medium: 500;
  --weight-semibold: 600;
  --weight-bold: 700;

  --leading-tight: 1.06;
  --leading-snug: 1.25;
  --leading-normal: 1.5;
  --leading-relaxed: 1.6;

  --tracking-tighter: -0.035em;
  --tracking-tight: -0.018em;
  --tracking-normal: 0;
  --tracking-wide: 0.06em;
  --tracking-wider: 0.12em;

  --measure: 62ch;

  /* ---------- spacing ---------- */
  --space-0: 0;
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.5rem;
  --space-6: 2rem;
  --space-7: 2.5rem;
  --space-8: 3rem;
  --space-9: 4rem;
  --space-10: 5rem;

  /* ---------- radii ---------- */
  --radius-xs: 4px;
  --radius-sm: 7px;
  --radius-md: 11px;
  --radius-lg: 16px;
  --radius-xl: 22px;
  --radius-screen: 14px;
  --radius-pill: 999px;

  /* ---------- layout ---------- */
  --shell-max: 1180px;
  --gutter: clamp(1rem, 3.4vw, 2.5rem);
  --spine-width: 4.75rem;
  --panel-pad: clamp(1rem, 2.1vw, 1.75rem);
  --panel-max-date: 46rem;
  --key-size: clamp(2.5rem, 2rem + 1.5vw, 3.25rem);
  --tap-min: 2.75rem;
  --hairline: 1px;
  --focus-width: 2px;
  --focus-offset: 2px;
  --plot-cell-x: 10%;
  --plot-cell-y: 12.5%;

  /* ---------- elevation ---------- */
  --shadow-panel: inset 0 1px 0 rgba(255, 255, 255, 0.7),
    0 1px 2px rgba(21, 33, 30, 0.05), 0 26px 60px -46px rgba(21, 33, 30, 0.55);
  --shadow-screen: inset 0 1px 0 rgba(255, 255, 255, 0.06),
    0 14px 34px -26px rgba(12, 23, 20, 0.75);
  --shadow-key: 0 1px 0 rgba(21, 33, 30, 0.14), 0 2px 5px -4px rgba(21, 33, 30, 0.35);
  --shadow-key-accent: 0 1px 0 rgba(10, 20, 17, 0.18), 0 6px 14px -10px var(--accent-strong);
  --shadow-focus: 0 0 0 var(--focus-width) var(--accent-strong);

  /* ---------- motion ---------- */
  --dur-instant: 90ms;
  --dur-fast: 150ms;
  --dur-base: 240ms;
  --dur-slow: 420ms;
  --ease-standard: cubic-bezier(0.22, 0.61, 0.36, 1);
  --ease-emphasis: cubic-bezier(0.2, 0.8, 0.2, 1);
}

/* ==========================================================================
   Per-mode accent + material overrides
   ========================================================================== */

body[data-mode="scientific"] {
  --accent: var(--accent-sci);
  --accent-strong: var(--accent-sci-strong);
  --accent-bright: var(--accent-sci-bright);
  --accent-soft: var(--accent-sci-soft);
  --accent-glow: var(--accent-sci-glow);
  --accent-ghost: var(--accent-sci-ghost);
  --page: var(--page-sci);
  --mode-texture: var(--texture-sci);
  --mode-texture-size: var(--texture-sci-size);
}

body[data-mode="graph"] {
  --accent: var(--accent-graph);
  --accent-strong: var(--accent-graph-strong);
  --accent-bright: var(--accent-graph-bright);
  --accent-soft: var(--accent-graph-soft);
  --accent-glow: var(--accent-graph-glow);
  --accent-ghost: var(--accent-graph-ghost);
  --page: var(--page-graph);
  --mode-texture: var(--texture-graph);
  --mode-texture-size: var(--texture-graph-size);
}

body[data-mode="date"] {
  --accent: var(--accent-date);
  --accent-strong: var(--accent-date-strong);
  --accent-bright: var(--accent-date-bright);
  --accent-soft: var(--accent-date-soft);
  --accent-glow: var(--accent-date-glow);
  --accent-ghost: var(--accent-date-ghost);
  --page: var(--page-date);
  --mode-texture: var(--texture-date);
  --mode-texture-size: var(--texture-date-size);
}

/* ==========================================================================
   Reduced motion: collapse the motion scale at the token level
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  :root {
    --dur-instant: 0.01ms;
    --dur-fast: 0.01ms;
    --dur-base: 0.01ms;
    --dur-slow: 0.01ms;
  }
}

/* ==========================================================================
   Axiom — layout, mode identity, and shared calculator primitives
   Depends on styles/tokens.css for every value used here.
   ========================================================================== */

/* ---------- base ---------- */

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  padding-top: calc(var(--hairline) * 3);
  background-color: var(--page);
  background-image: var(--mode-texture);
  background-size: var(--mode-texture-size);
  background-attachment: fixed;
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: var(--text-base);
  line-height: var(--leading-normal);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  transition: background-color var(--dur-slow) var(--ease-standard),
    color var(--dur-slow) var(--ease-standard);
}

[hidden] {
  display: none !important;
}

p {
  margin: 0 0 var(--space-3);
}

p:last-child {
  margin-bottom: 0;
}

h1,
h2,
h3 {
  margin: 0;
  line-height: var(--leading-snug);
  letter-spacing: var(--tracking-tight);
}

::selection {
  background: var(--accent-soft);
  color: var(--ink);
}

:where(a, button, input, select, summary, [tabindex]):focus-visible {
  outline: var(--focus-width) solid var(--accent-strong);
  outline-offset: var(--focus-offset);
}

/* ---------- utilities ---------- */

.sr-only {
  position: absolute !important;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

.skip-link {
  position: fixed;
  top: var(--space-2);
  left: var(--space-2);
  z-index: 40;
  padding: var(--space-2) var(--space-4);
  border: var(--hairline) solid var(--accent-strong);
  border-radius: var(--radius-sm);
  background: var(--paper-raised);
  color: var(--accent-strong);
  font-weight: var(--weight-semibold);
  text-decoration: none;
  transform: translateY(calc(-100% - var(--space-4)));
  transition: transform var(--dur-fast) var(--ease-emphasis);
}

.skip-link:focus-visible {
  transform: translateY(0);
}

/* Instrument status lamp: the accent stripe stays visible while scrolling. */
.mode-bar {
  position: fixed;
  inset: 0 0 auto 0;
  height: calc(var(--hairline) * 3);
  z-index: 30;
  background: var(--accent);
  transition: background-color var(--dur-base) var(--ease-standard);
}

/* ---------- masthead ---------- */

.masthead {
  width: 100%;
  max-width: var(--shell-max);
  margin-inline: auto;
  padding: var(--space-5) var(--gutter) 0;
  display: grid;
  gap: var(--space-4);
}

.masthead__top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3) var(--space-5);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: var(--space-3);
  min-width: 0;
}

.brand__mark {
  width: var(--space-6);
  height: var(--space-6);
  flex: none;
  color: var(--accent-strong);
  transition: color var(--dur-base) var(--ease-standard);
}

.brand__text {
  display: grid;
  gap: var(--space-0);
  min-width: 0;
}

.brand__name {
  font-size: var(--text-lg);
  font-weight: var(--weight-bold);
  letter-spacing: var(--tracking-tighter);
  line-height: var(--leading-tight);
}

.brand__tagline {
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
  letter-spacing: var(--tracking-wide);
  color: var(--ink-faint);
  line-height: var(--leading-snug);
}

/* Live mode readout: redundant with the tablist on purpose — the mode must be
   obvious while the tabs are scrolled out of view. */
.mode-status {
  display: none;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-2) var(--space-4) var(--space-2) var(--space-3);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius-pill);
  background: var(--paper-raised);
  box-shadow: var(--shadow-key);
}

body[data-mode="scientific"] .mode-status[data-for-mode="scientific"],
body[data-mode="graph"] .mode-status[data-for-mode="graph"],
body[data-mode="date"] .mode-status[data-for-mode="date"] {
  display: flex;
}

.mode-status__dot {
  width: var(--space-2);
  height: var(--space-2);
  flex: none;
  border-radius: var(--radius-pill);
  background: var(--accent);
  box-shadow: 0 0 0 var(--space-1) var(--accent-soft);
}

.mode-status__name {
  display: block;
  font-size: var(--text-sm);
  font-weight: var(--weight-semibold);
  letter-spacing: var(--tracking-tight);
  line-height: var(--leading-snug);
}

.mode-status__note {
  display: block;
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
  letter-spacing: var(--tracking-wide);
  color: var(--ink-faint);
  line-height: var(--leading-snug);
}

/* ---------- tablist ---------- */

.tablist {
  display: flex;
  gap: var(--space-1);
  padding: var(--space-1);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius-md);
  background: var(--paper-sunken);
  overflow-x: auto;
  scrollbar-width: thin;
}

.tab {
  --tab-accent: var(--accent-sci);
  --tab-strong: var(--accent-sci-strong);
  position: relative;
  flex: 1 1 0;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-2);
  min-height: var(--tap-min);
  padding: var(--space-2) var(--space-3);
  border: var(--hairline) solid transparent;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--ink-soft);
  font-family: var(--font-ui);
  font-size: var(--text-base);
  font-weight: var(--weight-medium);
  letter-spacing: var(--tracking-tight);
  cursor: pointer;
  transition: color var(--dur-fast) var(--ease-standard),
    background-color var(--dur-fast) var(--ease-standard),
    border-color var(--dur-fast) var(--ease-standard),
    box-shadow var(--dur-fast) var(--ease-standard);
}

.tab[data-mode="scientific"] {
  --tab-accent: var(--accent-sci);
  --tab-strong: var(--accent-sci-strong);
}

.tab[data-mode="graph"] {
  --tab-accent: var(--accent-graph);
  --tab-strong: var(--accent-graph-strong);
}

.tab[data-mode="date"] {
  --tab-accent: var(--accent-date);
  --tab-strong: var(--accent-date-strong);
}

.tab:hover {
  color: var(--ink);
  background: var(--paper);
}

.tab[aria-selected="true"] {
  color: var(--ink);
  background: var(--paper-raised);
  border-color: var(--line);
  box-shadow: var(--shadow-key);
}

.tab__dot {
  width: var(--space-2);
  height: var(--space-2);
  flex: none;
  border: var(--hairline) solid var(--tab-accent);
  border-radius: var(--radius-pill);
  background: transparent;
  transition: background-color var(--dur-fast) var(--ease-standard),
    box-shadow var(--dur-fast) var(--ease-standard);
}

.tab[aria-selected="true"] .tab__dot {
  background: var(--tab-accent);
  box-shadow: 0 0 0 var(--space-1) var(--accent-soft);
}

.tab__label {
  transition: color var(--dur-fast) var(--ease-standard);
}

.tab[aria-selected="true"] .tab__label {
  color: var(--tab-strong);
  font-weight: var(--weight-semibold);
}

.tab__meta {
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
  letter-spacing: var(--tracking-wide);
  color: var(--ink-faint);
}

.tab::after {
  content: "";
  position: absolute;
  left: var(--space-3);
  right: var(--space-3);
  bottom: var(--space-1);
  height: calc(var(--hairline) * 2);
  border-radius: var(--radius-pill);
  background: var(--tab-accent);
  opacity: 0;
  transform: scaleX(0.35);
  transition: opacity var(--dur-base) var(--ease-emphasis),
    transform var(--dur-base) var(--ease-emphasis);
}

.tab[aria-selected="true"]::after {
  opacity: 1;
  transform: scaleX(1);
}

/* ---------- stage + mode spine ---------- */

.stage {
  flex: 1;
  width: 100%;
  max-width: var(--shell-max);
  margin-inline: auto;
  padding: var(--space-5) var(--gutter) var(--space-8);
  display: grid;
  grid-template-columns: var(--spine-width) minmax(0, 1fr);
  gap: var(--space-4);
  align-items: start;
}

/* The one loud element: a vertical channel strip naming the active mode,
   textured with that mode's own material. */
.spine {
  position: sticky;
  top: var(--space-4);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: var(--space-4);
  min-height: min(34rem, calc(100vh - var(--space-8)));
  padding: var(--space-4) var(--space-2);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius-lg);
  background-color: var(--paper-raised);
  background-image: var(--mode-texture);
  background-size: var(--mode-texture-size);
  overflow: hidden;
}

.spine__rail {
  align-self: center;
  width: var(--space-1);
  height: var(--space-6);
  flex: none;
  border-radius: var(--radius-pill);
  background: var(--accent);
  transition: background-color var(--dur-base) var(--ease-standard);
}

.spine__word {
  display: none;
  align-self: center;
  margin: 0;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  font-size: var(--text-spine);
  font-weight: var(--weight-bold);
  letter-spacing: var(--tracking-tighter);
  line-height: var(--leading-tight);
  color: var(--accent-strong);
  opacity: 0.24;
  user-select: none;
}

body[data-mode="scientific"] .spine__word[data-for-mode="scientific"],
body[data-mode="graph"] .spine__word[data-for-mode="graph"],
body[data-mode="date"] .spine__word[data-for-mode="date"] {
  display: block;
}

/* ---------- panel ---------- */

.panel {
  position: relative;
  padding: var(--panel-pad);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius-xl);
  background-color: var(--paper-raised);
  background-image: linear-gradient(180deg, var(--accent-soft), transparent var(--space-10));
  box-shadow: inset 0 calc(var(--hairline) * 3) 0 0 var(--accent), var(--shadow-panel);
  animation: panel-in var(--dur-slow) var(--ease-emphasis) both;
}

@keyframes panel-in {
  from {
    opacity: 0;
    transform: translateY(var(--space-2));
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.panel__head {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  justify-content: space-between;
  gap: var(--space-2) var(--space-4);
  margin-bottom: var(--space-4);
  padding-bottom: var(--space-2);
  border-bottom: var(--hairline) solid var(--line);
}

.panel__title-group {
  display: grid;
  gap: var(--space-1);
  min-width: 0;
}

.panel__title {
  font-size: var(--text-xl);
  font-weight: var(--weight-semibold);
  letter-spacing: var(--tracking-tighter);
}

.panel__note {
  max-width: var(--measure);
  margin: 0;
  font-size: var(--text-sm);
  line-height: var(--leading-normal);
  color: var(--ink-soft);
}

.panel__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2);
}

.panel__body {
  display: grid;
  gap: var(--space-4);
}

.panel__rail {
  display: grid;
  gap: var(--space-4);
  align-content: start;
  min-width: 0;
}

/* ---------- readout (dark glass) ---------- */

.readout {
  position: relative;
  display: grid;
  gap: var(--space-2);
  padding: var(--space-4) var(--space-5);
  border: var(--hairline) solid var(--screen-edge);
  border-radius: var(--radius-screen);
  background-color: var(--screen);
  background-image: var(--screen-sheen);
  box-shadow: var(--shadow-screen);
  overflow: hidden;
}

.readout::after {
  content: "";
  position: absolute;
  inset: auto 0 0 0;
  height: calc(var(--hairline) * 2);
  background: var(--accent);
  opacity: 0.85;
}

.readout__expr {
  min-height: 1.4em;
  margin: 0;
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  letter-spacing: var(--tracking-wide);
  color: var(--screen-soft);
  overflow-wrap: anywhere;
}

.readout__value {
  margin: 0;
  font-family: var(--font-mono);
  font-size: var(--text-readout);
  font-weight: var(--weight-medium);
  letter-spacing: var(--tracking-tighter);
  line-height: var(--leading-tight);
  text-align: right;
  color: var(--screen-ink);
  font-variant-numeric: tabular-nums;
  text-shadow: 0 0 var(--space-5) var(--accent-glow);
  overflow-wrap: anywhere;
}

.readout__suffix {
  font-size: var(--text-md);
  font-weight: var(--weight-regular);
  letter-spacing: var(--tracking-wide);
  color: var(--accent-bright);
}

.readout__meta {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-1) var(--space-3);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  letter-spacing: var(--tracking-wide);
  color: var(--screen-faint);
}

.readout__meta .is-accent {
  color: var(--accent-bright);
}

/* ---------- keypad + keys ---------- */

.keypad {
  display: grid;
  grid-template-columns: repeat(var(--keypad-cols, 5), minmax(0, 1fr));
  gap: var(--space-2);
}

.key {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: var(--key-size);
  padding: var(--space-2) var(--space-1);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius-sm);
  background: var(--paper-raised);
  box-shadow: var(--shadow-key);
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: var(--text-md);
  font-weight: var(--weight-medium);
  font-variant-numeric: tabular-nums;
  letter-spacing: var(--tracking-normal);
  cursor: pointer;
  transition: background-color var(--dur-instant) var(--ease-standard),
    border-color var(--dur-instant) var(--ease-standard),
    box-shadow var(--dur-instant) var(--ease-standard),
    transform var(--dur-instant) var(--ease-standard);
}

.key:hover {
  background: var(--paper);
  border-color: var(--line-strong);
}

.key:active {
  transform: translateY(calc(var(--hairline) * 2));
  box-shadow: none;
  background: var(--paper-sunken);
}

.key--fn {
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  color: var(--ink-soft);
}

.key--op {
  font-family: var(--font-mono);
  font-size: var(--text-md);
  font-weight: var(--weight-semibold);
  color: var(--accent-strong);
  background: var(--paper);
}

.key--op:hover {
  background: var(--accent-soft);
  border-color: var(--accent);
}

.key--equals {
  grid-column: span 2;
  border-color: var(--accent-strong);
  background: var(--accent-strong);
  color: var(--on-accent);
  font-family: var(--font-mono);
  font-size: var(--text-md);
  font-weight: var(--weight-semibold);
  box-shadow: var(--shadow-key-accent);
}

.key--equals:hover {
  background: var(--accent);
  border-color: var(--accent);
}

.key--equals:active {
  background: var(--accent-strong);
}

.key[aria-pressed="true"] {
  border-color: var(--accent);
  background: var(--accent-soft);
  color: var(--accent-strong);
}

/* ---------- fields ---------- */

.field-row {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(10rem, 1fr));
  gap: var(--space-3);
  align-items: end;
}

.field {
  display: grid;
  gap: var(--space-1);
  min-width: 0;
}

.field__label {
  font-size: var(--text-xs);
  font-weight: var(--weight-medium);
  letter-spacing: var(--tracking-wide);
  color: var(--ink-soft);
}

.field__hint {
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
  letter-spacing: var(--tracking-wide);
  color: var(--ink-faint);
}

.input,
.select {
  width: 100%;
  min-height: var(--tap-min);
  padding: var(--space-2) var(--space-3);
  border: var(--hairline) solid var(--line-strong);
  border-radius: var(--radius-sm);
  background: var(--paper);
  color: var(--ink);
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  letter-spacing: var(--tracking-tight);
  font-variant-numeric: tabular-nums;
  transition: border-color var(--dur-fast) var(--ease-standard),
    background-color var(--dur-fast) var(--ease-standard);
}

.select {
  font-family: var(--font-ui);
  font-size: var(--text-base);
}

.input:hover,
.select:hover {
  border-color: var(--accent);
}

.input:focus-visible,
.select:focus-visible {
  border-color: var(--accent-strong);
  background: var(--paper-raised);
  outline-offset: var(--focus-offset);
}

/* ---------- chips ---------- */

.chip {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
  min-height: calc(var(--tap-min) * 0.7);
  padding: 0 var(--space-3);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius-pill);
  background: var(--paper-raised);
  color: var(--ink-soft);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  letter-spacing: var(--tracking-wide);
  line-height: var(--leading-tight);
  white-space: nowrap;
}

.chip--accent {
  border-color: var(--accent);
  background: var(--accent-soft);
  color: var(--accent-strong);
}

.chip__dot {
  width: calc(var(--space-1) + var(--hairline));
  height: calc(var(--space-1) + var(--hairline));
  flex: none;
  border-radius: var(--radius-pill);
  background: currentColor;
}

button.chip {
  cursor: pointer;
  transition: border-color var(--dur-fast) var(--ease-standard),
    background-color var(--dur-fast) var(--ease-standard);
}

button.chip:hover {
  border-color: var(--line-strong);
  background: var(--paper);
}

/* ---------- plot ---------- */

.plot {
  display: grid;
  gap: var(--space-2);
  margin: 0;
  min-width: 0;
}

.plot__caption {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  letter-spacing: var(--tracking-wide);
  color: var(--ink-faint);
}

.plot__fn {
  font-size: var(--text-sm);
  color: var(--accent-strong);
  font-weight: var(--weight-medium);
}

.plot__frame {
  position: relative;
  padding: var(--space-3);
  border: var(--hairline) solid var(--screen-edge);
  border-radius: var(--radius-md);
  background-color: var(--screen);
  background-image: var(--screen-sheen);
  box-shadow: var(--shadow-screen);
  overflow: hidden;
}

.plot__grid {
  position: absolute;
  inset: 0;
  background-image: linear-gradient(to right, var(--screen-line) var(--hairline), transparent var(--hairline)),
    linear-gradient(to bottom, var(--screen-line) var(--hairline), transparent var(--hairline));
  background-size: var(--plot-cell-x) var(--plot-cell-y);
  pointer-events: none;
}

.plot__svg {
  position: relative;
  display: block;
  width: 100%;
  height: auto;
  overflow: visible;
}

.plot__axis {
  stroke: var(--screen-soft);
  stroke-width: 1;
  opacity: 0.7;
}

.plot__tick {
  fill: var(--screen-faint);
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
}

.plot__curve {
  fill: none;
  stroke: var(--accent-bright);
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.plot__origin {
  fill: var(--accent-bright);
  stroke: var(--screen);
  stroke-width: 2;
}

.plot__legend {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
  letter-spacing: var(--tracking-wide);
  color: var(--ink-faint);
}

.plot__legend span {
  display: inline-flex;
  align-items: center;
  gap: var(--space-1);
}

.plot__swatch {
  width: var(--space-3);
  height: calc(var(--hairline) * 2);
  border-radius: var(--radius-pill);
  background: var(--accent);
}

/* ---------- data list ---------- */

.data {
  display: grid;
  gap: var(--space-2);
  min-width: 0;
}

.data__title {
  margin: 0;
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  font-weight: var(--weight-medium);
  letter-spacing: var(--tracking-wide);
  color: var(--ink-faint);
}

.data dl {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 0 var(--space-3);
  margin: 0;
}

.data dt,
.data dd {
  padding-block: var(--space-2);
  border-bottom: var(--hairline) solid var(--line);
}

.data dt {
  margin: 0;
  align-self: center;
  font-size: var(--text-sm);
  color: var(--ink-soft);
}

.data dd {
  margin: 0;
  align-self: center;
  font-family: var(--font-mono);
  font-size: var(--text-sm);
  font-variant-numeric: tabular-nums;
  letter-spacing: var(--tracking-tight);
  color: var(--ink);
  text-align: right;
}

.data dd.is-accent {
  color: var(--accent-strong);
}

.data dl > :nth-last-child(-n + 2) {
  padding-bottom: 0;
  border-bottom: 0;
}

/* ---------- timeline (date mode visual) ---------- */

.timeline {
  display: grid;
  gap: var(--space-2);
  padding: var(--space-3) var(--space-4) var(--space-4);
  border: var(--hairline) solid var(--line);
  border-radius: var(--radius-md);
  background: var(--paper);
}

.timeline__ends {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: var(--space-1) var(--space-3);
  font-family: var(--font-mono);
  font-size: var(--text-xs);
  letter-spacing: var(--tracking-wide);
  color: var(--ink-soft);
}

.timeline__track {
  position: relative;
  height: var(--space-2);
  border-radius: var(--radius-pill);
  background-color: var(--paper-deep);
  background-image: repeating-linear-gradient(
    90deg,
    var(--line-strong) 0 var(--hairline),
    transparent var(--hairline) 10%
  );
}

.timeline__fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: var(--fill, 100%);
  border-radius: inherit;
  background: var(--accent);
}

.timeline__marker {
  position: absolute;
  top: 50%;
  left: var(--fill, 100%);
  width: var(--space-3);
  height: var(--space-3);
  border: calc(var(--hairline) * 2) solid var(--paper);
  border-radius: var(--radius-pill);
  background: var(--accent);
  box-shadow: 0 0 0 var(--space-1) var(--accent-soft);
  transform: translate(-50%, -50%);
}

.timeline__note {
  margin: 0;
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
  letter-spacing: var(--tracking-wide);
  color: var(--ink-faint);
}

/* ---------- per-mode layouts: the page itself changes shape ---------- */

/* Scientific: readout over a dense keypad + instrument data rail. */
.panel--scientific .panel__body {
  grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr);
  align-items: start;
}

.panel--scientific .readout {
  grid-column: 1 / -1;
}

/* Graph: a wide plotting screen with a slim readout rail. */
.panel--graph .panel__body {
  grid-template-columns: minmax(0, 1.6fr) minmax(0, 0.8fr);
}

.panel--graph .field-row {
  grid-column: 1 / -1;
}

/* Date: a narrow centred ledger, roomier rhythm. */
.panel--date {
  max-width: var(--panel-max-date);
  margin-inline: auto;
  background-image: linear-gradient(180deg, var(--accent-soft), transparent var(--space-10));
}

.panel--date .panel__body {
  grid-template-columns: minmax(0, 1fr);
  gap: var(--space-5);
}

/* ---------- footer ---------- */

.footer {
  width: 100%;
  max-width: var(--shell-max);
  margin-inline: auto;
  padding: var(--space-5) var(--gutter) var(--space-7);
  display: grid;
  gap: var(--space-1);
  border-top: var(--hairline) solid var(--line);
  color: var(--ink-faint);
  font-size: var(--text-sm);
}

.footer__note {
  margin: 0;
}

.footer__hint {
  margin: 0;
  font-family: var(--font-mono);
  font-size: var(--text-2xs);
  letter-spacing: var(--tracking-wide);
}

/* ---------- responsive ---------- */

@media (max-width: 900px) {
  .panel--scientific .panel__body,
  .panel--graph .panel__body {
    grid-template-columns: minmax(0, 1fr);
  }

  .panel--scientific .readout,
  .panel--graph .field-row {
    grid-column: auto;
  }
}

@media (max-width: 720px) {
  .stage {
    grid-template-columns: minmax(0, 1fr);
    padding-top: var(--space-4);
  }

  .spine {
    position: relative;
    top: auto;
    flex-direction: row;
    align-items: center;
    justify-content: flex-start;
    gap: var(--space-3);
    min-height: 0;
    padding: var(--space-3) var(--space-4);
    border-radius: var(--radius-md);
  }

  .spine__rail {
    width: var(--space-6);
    height: var(--space-1);
    align-self: center;
  }

  .spine__word {
    writing-mode: horizontal-tb;
    transform: none;
    font-size: var(--text-lg);
    opacity: 0.32;
  }

  .tab {
    flex: 1 1 auto;
    padding-inline: var(--space-2);
    font-size: var(--text-sm);
  }

  .tab__meta {
    display: none;
  }

  .panel {
    border-radius: var(--radius-lg);
  }

  .readout {
    padding: var(--space-3) var(--space-4);
  }

  .keypad {
    --keypad-cols: 4;
  }

  .mode-status {
    order: 3;
    width: 100%;
    justify-content: flex-start;
  }
}

@media (max-width: 420px) {
  .brand__tagline {
    display: none;
  }

  .masthead__top {
    gap: var(--space-2);
  }
}

/* ---------- reduced motion ---------- */

@media (prefers-reduced-motion: reduce) {
  body {
    background-attachment: scroll;
  }

  .panel {
    animation: none;
  }

  .key:active {
    transform: none;
  }

  .tab::after {
    transform: none;
  }

  .skip-link {
    transition: none;
  }
}

