/* ==========================================================================
   Axiom — mode controller
   Plain global script (no modules, no build step) so the page works from file://

   Public API:  window.Calc
     Calc.mode              current mode: "scientific" | "graph" | "date"
     Calc.modes             ordered list of modes
     Calc.setMode(mode)     switch mode (updates body[data-mode], tabs, hash)
     Calc.announce(text)    push a message to the polite live region
     Calc.reducedMotion     true when prefers-reduced-motion: reduce matches
     Calc.tabFor(mode)      the tab button element for a mode

   Events on document (for the panels built in later tasks):
     calc:ready       { mode }                  fired once on load
     calc:modechange  { mode, previous }        fired on every real change
   ========================================================================== */

(function (window, document) {
  'use strict';

  var MODES = ['scientific', 'graph', 'date'];
  var LABELS = { scientific: 'Scientific', graph: 'Graph', date: 'Date' };
  var DEFAULT_MODE = 'scientific';

  var body = document.body;
  var tablist = document.querySelector('[data-tablist]');
  var tabs = Array.prototype.slice.call(
    document.querySelectorAll('[role="tab"][data-mode]')
  );
  var panels = Array.prototype.slice.call(
    document.querySelectorAll('[role="tabpanel"]')
  );
  var live = document.getElementById('mode-announcer');

  var motionQuery =
    typeof window.matchMedia === 'function'
      ? window.matchMedia('(prefers-reduced-motion: reduce)')
      : null;

  var announceTimer = null;

  function isValid(mode) {
    return MODES.indexOf(mode) !== -1;
  }

  function modeFromHash() {
    var raw = (window.location.hash || '').replace(/^#\/?/, '').toLowerCase();
    return isValid(raw) ? raw : null;
  }

  function tabFor(mode) {
    for (var i = 0; i < tabs.length; i += 1) {
      if (tabs[i].getAttribute('data-mode') === mode) return tabs[i];
    }
    return null;
  }

  function panelFor(mode) {
    for (var i = 0; i < panels.length; i += 1) {
      if (panels[i].id === 'panel-' + mode) return panels[i];
    }
    return null;
  }

  /* Keep the address bar in step without adding history entries or scrolling. */
  function syncHash(mode) {
    if (window.location.hash === '#' + mode) return;
    var url = window.location.pathname + window.location.search + '#' + mode;
    try {
      window.history.replaceState(null, '', url);
    } catch (error) {
      /* Some browsers block history writes on file:// — the mode still changes. */
    }
  }

  /* Screen-reader announcement. Cleared first so repeat messages are spoken. */
  function announce(text) {
    if (!live || !text) return;
    if (announceTimer) window.clearTimeout(announceTimer);
    live.textContent = '';
    announceTimer = window.setTimeout(function () {
      live.textContent = String(text);
      announceTimer = null;
    }, 60);
  }

  function setMode(next, options) {
    options = options || {};
    if (!isValid(next)) return Calc.mode;

    var previous = Calc.mode;
    var changed = previous !== next;

    body.setAttribute('data-mode', next);
    Calc.mode = next;

    tabs.forEach(function (tab) {
      var active = tab.getAttribute('data-mode') === next;
      tab.setAttribute('aria-selected', active ? 'true' : 'false');
      tab.tabIndex = active ? 0 : -1;
    });

    panels.forEach(function (panel) {
      if (panel.id === 'panel-' + next) {
        panel.removeAttribute('hidden');
      } else {
        panel.setAttribute('hidden', '');
      }
    });

    if (!options.fromHash) syncHash(next);

    if (changed && !options.silent) {
      announce(LABELS[next] + ' mode');
    }

    if (changed) {
      document.dispatchEvent(
        new CustomEvent('calc:modechange', {
          detail: { mode: next, previous: previous }
        })
      );
    }

    if (options.focusTab) {
      var target = tabFor(next);
      if (target) target.focus();
    }

    return next;
  }

  /* Arrow keys / Home / End move through the tablist (automatic activation). */
  function onTablistKeydown(event) {
    var index = MODES.indexOf(Calc.mode);
    var next = null;

    switch (event.key) {
      case 'ArrowRight':
      case 'ArrowDown':
        next = MODES[(index + 1) % MODES.length];
        break;
      case 'ArrowLeft':
      case 'ArrowUp':
        next = MODES[(index - 1 + MODES.length) % MODES.length];
        break;
      case 'Home':
        next = MODES[0];
        break;
      case 'End':
        next = MODES[MODES.length - 1];
        break;
      default:
        return;
    }

    event.preventDefault();
    setMode(next, { focusTab: true });
  }

  function onTablistClick(event) {
    var target = event.target;
    var tab = target && target.closest ? target.closest('[role="tab"]') : null;
    if (!tab || tabs.indexOf(tab) === -1) return;
    setMode(tab.getAttribute('data-mode'));
  }

  function onHashChange() {
    var mode = modeFromHash();
    if (mode && mode !== Calc.mode) {
      setMode(mode, { fromHash: true });
    }
  }

  function readMotionPreference() {
    Calc.reducedMotion = motionQuery ? motionQuery.matches : false;
    body.classList.toggle('reduce-motion', Calc.reducedMotion);
  }

  var Calc = {
    mode: DEFAULT_MODE,
    modes: MODES.slice(),
    labels: LABELS,
    reducedMotion: motionQuery ? motionQuery.matches : false,
    setMode: setMode,
    announce: announce,
    tabFor: tabFor
  };

  window.Calc = Calc;

  readMotionPreference();
  if (motionQuery) {
    if (typeof motionQuery.addEventListener === 'function') {
      motionQuery.addEventListener('change', readMotionPreference);
    } else if (typeof motionQuery.addListener === 'function') {
      motionQuery.addListener(readMotionPreference);
    }
  }

  if (tablist) {
    tablist.addEventListener('keydown', onTablistKeydown);
    tablist.addEventListener('click', onTablistClick);
  }
  window.addEventListener('hashchange', onHashChange);

  var startMode = modeFromHash();
  setMode(startMode || DEFAULT_MODE, { silent: true, fromHash: Boolean(startMode) });

  document.dispatchEvent(
    new CustomEvent('calc:ready', { detail: { mode: Calc.mode } })
  );
})(window, document);

